// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 v) public {

        bool okBefore;
        try c.SetMinSum(v) {
            okBefore = true;
        } catch {
            okBefore = false;
        }

        c.Initialized();

        bool okAfter;
        try c.SetMinSum(v) {
            okAfter = true;
        } catch {
            okAfter = false;
        }

        assertTrue(okBefore && !okAfter);
    }
}
